#!/usr/bin/env python3
"""
Attrium ClickGUI Bind Final Fixer (Fabric 1.21.11)
- Hooks GlassClickGuiScreen.pollGlobalKeybinds() directly from HudManager.renderInGameHud
  (100% guaranteed to run from frame 1 in-game even before ClickGUI is ever opened).
- Consumes the ClickGUI GLFW key press cleanly and dispatches mc.execute(() -> openClickGuiFromBind(mc))
  on Minecraft's render thread (fixes FoldCraftLauncher / LWJGL thread timing).
- Shows a "Bind set to <KEY>" toast on rebind, verifies TickPipelineMixin in mixins.json,
  and disables any external duplicate ClickGUI openers.
"""
import base64
import json
import os
import re
import sys

FILES_B64 = {
    "attrium/ru/manager/ClientThemeManager.java": "",
    "attrium/ru/manager/FriendManager.java": "",
    "attrium/ru/manager/HudManager.java": "",
    "attrium/ru/screens/GlassClickGuiScreen.java": "",

}


def ensure_tick_mixin(cwd):
    res_dir = os.path.join(cwd, "src", "main", "resources")
    if not os.path.isdir(res_dir):
        return
    for root, _, files in os.walk(res_dir):
        for fn in files:
            if fn.endswith("mixins.json"):
                path = os.path.join(root, fn)
                try:
                    with open(path, "r", encoding="utf-8") as f:
                        data = json.load(f)
                    key = "client" if "client" in data and isinstance(data["client"], list) else "mixins"
                    if key not in data or not isinstance(data[key], list):
                        data[key] = []
                    if "TickPipelineMixin" not in data[key]:
                        data[key].append("TickPipelineMixin")
                        with open(path, "w", encoding="utf-8") as f:
                            json.dump(data, f, indent=2)
                        print(f"[MIXIN] Added TickPipelineMixin to {os.path.relpath(path, cwd)}")
                except Exception as e:
                    print(f"[WARN] Could not inspect {fn}: {e}")


def disable_external_openers(src_root):
    skip_files = {
        "GlassClickGuiScreen.java",
        "ClientThemeManager.java",
        "HudManager.java",
        "FriendManager.java",
        "KeybindsModule.java",
        "TickPipelineManager.java",
    }
    for root, _, files in os.walk(src_root):
        for fn in files:
            if not fn.endswith(".java") or fn in skip_files:
                continue
            path = os.path.join(root, fn)
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                src = f.read()
            if "GlassClickGuiScreen" not in src:
                continue
            orig = src
            src = re.sub(
                r"([ \t]*)([^;\n]*\.setScreen\s*\([^;\n]*GlassClickGuiScreen[^;\n]*\)\s*;)",
                r"\1/* disabled legacy ClickGUI opener: \2 */",
                src,
            )
            if src != orig:
                with open(path, "w", encoding="utf-8") as f:
                    f.write(src)
                print(f"[DISABLED LEGACY OPENER] {os.path.relpath(path, src_root)}")


def main():
    cwd = os.getcwd()
    src_root = os.path.join(cwd, "src", "main", "java")
    if not os.path.isdir(src_root):
        print(f"[ERROR] Run this script from your project root (missing {src_root}).")
        sys.exit(1)
    for rel_path, b64_data in FILES_B64.items():
        out_path = os.path.join(src_root, *rel_path.split("/"))
        os.makedirs(os.path.dirname(out_path), exist_ok=True)
        with open(out_path, "wb") as f:
            f.write(base64.b64decode(b64_data))
        print(f"[OK] Wrote {rel_path}")
    ensure_tick_mixin(cwd)
    disable_external_openers(src_root)
    print("\nClickGUI bind final fix applied! Run: ./gradlew build --no-daemon")


if __name__ == "__main__":
    main()